#!/usr/bin/env bash
# Question 12: One worker takes no Pods. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q12_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q12_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q12_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
for n in "worker-1" "worker-2"; do kubectl label node "$n" tier=app --overwrite >/dev/null; done
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: spread
  namespace: ${Q12_NS}
spec:
  replicas: 0
  selector:
    matchLabels: { app: spread }
  template:
    metadata:
      labels: { app: spread }
    spec:
      affinity:
        nodeAffinity:
          requiredDuringSchedulingIgnoredDuringExecution:
            nodeSelectorTerms:
              - matchExpressions: [{ key: tier, operator: In, values: [app] }]
        podAntiAffinity:
          requiredDuringSchedulingIgnoredDuringExecution:
            - topologyKey: kubernetes.io/hostname
              labelSelector:
                matchLabels: { app: spread }
      containers:
        - name: web
          image: nginx:1.27-alpine
          resources:
            requests: { cpu: 10m, memory: 16Mi }
EOF
kubectl -n "${Q12_NS}" get deployment spread -o jsonpath='{.metadata.uid} {.spec.template.spec}' > "/var/tmp/cka-q12.deploy"
chmod 644 "/var/tmp/cka-q12.deploy"

case "${Q12_FAULT}" in
  cordoned)
    kubectl cordon "${Q12_NODE}"
    ;;
  taint-noschedule)
    kubectl taint node "${Q12_NODE}" dedicated=gpu:NoSchedule --overwrite
    ;;
  taint-noexecute)
    kubectl taint node "${Q12_NODE}" maintenance=true:NoExecute --overwrite
    ;;
  label-removed)
    kubectl label node "${Q12_NODE}" tier-
    ;;
  max-pods) ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
